_PTS = np.array([[float(a) for a in p.split(",")] for p in _RAW.split(";")])     # lon, lat
_A, _B = _PTS[:-1], _PTS[1:]


def offshore_nm(lat: float, lon: float) -> float:
    """Distance (NM) from a point to the nearest piece of the mainland coastline."""
    k = math.cos(math.radians(lat))
    ax, ay = (_A[:, 0] - lon) * k * 60, (_A[:, 1] - lat) * 60
    bx, by = (_B[:, 0] - lon) * k * 60, (_B[:, 1] - lat) * 60
    dx, dy = bx - ax, by - ay
    L = dx * dx + dy * dy
    t = np.clip(np.where(L > 0, -(ax * dx + ay * dy) / np.where(L > 0, L, 1), 0), 0, 1)
    px, py = ax + t * dx, ay + t * dy
    return float(np.sqrt(px * px + py * py).min())


def quiet_zone(lat: float, lon: float) -> str | None:
    for name, (w, s, e, n) in QUIET_ZONES.items():
        if w <= lon <= e and s <= lat <= n:
            return name
    return None


def spotter_waters(lat: float, lon: float) -> bool:
    """True where a circling plane can count as a spotter: far enough offshore and not in a quiet zone."""
    return quiet_zone(lat, lon) is None and offshore_nm(lat, lon) >= OFFSHORE_NM
